    diagram: { type: "linearGraph", params: { slope: 3, yIntercept: -4, xRange: [-2, 6], yRange: [-10, 14], xTickInterval: 2, yTickInterval: 4, gridInterval: 2, showPoints: [[0, -4], [2, 2]], label: "n" } },
