      // distractor: misreads "3 times" as a total of 3 tickets
      { id: "C", text: "$a + c = 3$ and $14a + 9c = 2{,}460$" },
      { id: "D", text: "$c = 3a$ and $14a + 9c = 2{,}460$" }
