    questionTable: { headers: ["Setpoint index $s$", "First gauge (kPa)", "Second gauge (kPa)"], rows: [["$1$", "$25$", "$29$"], ["$2$", "$35$", "$37$"], ["$5$", "$65$", "$61$"]] },
